import{_ as a,o as e,c as s,a2 as d}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"全文検索","description":"","frontmatter":{},"headers":[],"relativePath":"ja/advanced/search.md","filePath":"ja/advanced/search.md","lastUpdated":1784903584000}'),n={name:"ja/advanced/search.md"};function o(p,t,l,c,i,r){return e(),s("div",null,[...t[0]||(t[0]=[d(`<h1 id="全文検索" tabindex="-1">全文検索 <a class="header-anchor" href="#全文検索" aria-label="Permalink to &quot;全文検索&quot;">​</a></h1><h2 id="概要" tabindex="-1">概要 <a class="header-anchor" href="#概要" aria-label="Permalink to &quot;概要&quot;">​</a></h2><p>swag2mcp には組み込みの全文検索エンジン（bluge）が含まれており、すべての spec の全エンドポイントをインデックス化します。LLM はエンドポイント ID を知らなくても、メソッド、パス、サマリー、タグでエンドポイントを検索できます。</p><h2 id="インデックス化の仕組み" tabindex="-1">インデックス化の仕組み <a class="header-anchor" href="#インデックス化の仕組み" aria-label="Permalink to &quot;インデックス化の仕組み&quot;">​</a></h2><p>spec が追加または更新されると、すべてのエンドポイントがインデックス化されます。以下のフィールドが検索可能です：</p><table tabindex="0"><thead><tr><th>フィールド</th><th>説明</th><th>例</th></tr></thead><tbody><tr><td><code>method</code></td><td>HTTP メソッド</td><td><code>GET</code>、<code>POST</code>、<code>PUT</code></td></tr><tr><td><code>path</code></td><td>API エンドポイントパス</td><td><code>/api/v1/users/{id}</code></td></tr><tr><td><code>summary</code></td><td>OpenAPI サマリー</td><td>&quot;Find pet by ID&quot;</td></tr><tr><td><code>tag</code></td><td>エンドポイントカテゴリ</td><td>&quot;pets&quot;、&quot;users&quot;</td></tr><tr><td><code>_all</code></td><td>全フィールドの組み合わせ</td><td>method + path + tag + summary</td></tr></tbody></table><p>インデックスは MCP サーバー起動時に毎回再構築されます。高速検索のためにメモリ内に保存されます。</p><h2 id="クエリ構文" tabindex="-1">クエリ構文 <a class="header-anchor" href="#クエリ構文" aria-label="Permalink to &quot;クエリ構文&quot;">​</a></h2><p>検索は正確なフィルタリングのための豊富なクエリ構文をサポートしています：</p><table tabindex="0"><thead><tr><th>例</th><th>説明</th></tr></thead><tbody><tr><td><code>pet</code></td><td>全フィールドのシンプルなテキスト検索</td></tr><tr><td><code>method:GET</code></td><td>すべての GET エンドポイントを検索</td></tr><tr><td><code>tag:pets</code></td><td>&quot;pets&quot; タグ内のエンドポイントを検索</td></tr><tr><td><code>path:&quot;/api/v1/users&quot;</code></td><td>正確なパス一致</td></tr><tr><td><code>+method:POST +tag:pet</code></td><td>両方の条件に一致する必要あり</td></tr><tr><td><code>-method:DELETE</code></td><td>DELETE メソッドを除外</td></tr><tr><td><code>create~</code></td><td>あいまい検索（タイポ許容）</td></tr><tr><td><code>cr*</code></td><td>ワイルドカード検索</td></tr><tr><td><code>&quot;find pet&quot;</code></td><td>フレーズ検索</td></tr><tr><td><code>+summary:pet -method:DELETE</code></td><td>サマリーに &quot;pet&quot; を含み、DELETE を除外</td></tr></tbody></table><h3 id="フィールド固有の検索" tabindex="-1">フィールド固有の検索 <a class="header-anchor" href="#フィールド固有の検索" aria-label="Permalink to &quot;フィールド固有の検索&quot;">​</a></h3><p><code>field:value</code> 構文を使用して特定のフィールド内を検索できます：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>method:GET</span></span>
<span class="line"><span>tag:pets</span></span>
<span class="line"><span>path:&quot;/pet/findByStatus&quot;</span></span>
<span class="line"><span>summary:&quot;find pet by status&quot;</span></span></code></pre></div><h3 id="ブール演算子" tabindex="-1">ブール演算子 <a class="header-anchor" href="#ブール演算子" aria-label="Permalink to &quot;ブール演算子&quot;">​</a></h3><ul><li><code>+</code> — 用語が一致する必要あり（AND）</li><li><code>-</code> — 用語が一致してはいけない（NOT）</li><li>用語間のスペース — OR（いずれかの用語が一致）</li></ul><h3 id="あいまい検索とワイルドカード" tabindex="-1">あいまい検索とワイルドカード <a class="header-anchor" href="#あいまい検索とワイルドカード" aria-label="Permalink to &quot;あいまい検索とワイルドカード&quot;">​</a></h3><ul><li><code>term~</code> — あいまい検索（類似単語に一致、タイポ対応）</li><li><code>te*</code> — ワイルドカード（任意の文字に一致）</li><li><code>te?t</code> — 1 文字のワイルドカード</li></ul><h2 id="例" tabindex="-1">例 <a class="header-anchor" href="#例" aria-label="Permalink to &quot;例&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># すべての GET リクエストを検索</span></span>
<span class="line"><span>method:GET</span></span>
<span class="line"><span></span></span>
<span class="line"><span># pet タグ内の POST リクエストを検索</span></span>
<span class="line"><span>+method:POST +tag:pet</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 正確なパスでエンドポイントを検索</span></span>
<span class="line"><span>path:&quot;/pet/findByStatus&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 説明で検索</span></span>
<span class="line"><span>&quot;find pet by status&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span># DELETE 以外をすべて検索</span></span>
<span class="line"><span>+summary:pet -method:DELETE</span></span>
<span class="line"><span></span></span>
<span class="line"><span># &quot;create&quot; のあいまい検索（タイポ対応）</span></span>
<span class="line"><span>create~</span></span></code></pre></div><h2 id="mcp-ツール" tabindex="-1">MCP ツール <a class="header-anchor" href="#mcp-ツール" aria-label="Permalink to &quot;MCP ツール&quot;">​</a></h2><p><code>search</code> MCP ツールは検索エンジンを LLM に公開します：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>→ search(query: &quot;find pet by status&quot;, limit: 5)</span></span>
<span class="line"><span>← GET /pet/findByStatus — Finds Pets by status</span></span>
<span class="line"><span>   GET /pet/{petId} — Find pet by ID</span></span></code></pre></div><h3 id="パラメーター" tabindex="-1">パラメーター <a class="header-anchor" href="#パラメーター" aria-label="Permalink to &quot;パラメーター&quot;">​</a></h3><table tabindex="0"><thead><tr><th>パラメーター</th><th>必須</th><th>説明</th></tr></thead><tbody><tr><td><code>query</code></td><td>はい</td><td>検索クエリ（構造化構文をサポート）</td></tr><tr><td><code>limit</code></td><td>はい</td><td>最大結果数（1〜50）</td></tr></tbody></table><h2 id="重要な注意点" tabindex="-1">重要な注意点 <a class="header-anchor" href="#重要な注意点" aria-label="Permalink to &quot;重要な注意点&quot;">​</a></h2><ul><li><strong>インデックスはメモリ内</strong> — MCP サーバーが起動するたびに再構築されます。永続的なインデックスファイルはありません。</li><li><strong>すべてのフィールドは小文字化</strong> — 検索は大文字小文字を区別しません</li><li><strong>制限は最大 50</strong> — 50 を超える結果を要求することはできません</li><li><strong>無効なクエリ構文</strong> は例を含む役立つエラーメッセージを返します</li><li><strong><code>_all</code> フィールド</strong> はシンプルなテキスト検索のために method、path、tag、summary を結合します</li></ul>`,26)])])}const b=a(n,[["render",o]]);export{u as __pageData,b as default};
